import { brandUrl } from "./brand-assets";
import {
  conversationReportFilename,
  counselReportFilename,
  formatCounselReportPlaintext,
  reportReference,
  stripCitationMarkers,
  type ConversationReportPayload,
  type CounselReportPayload,
  type CounselReportSource,
  type CounselReportTurn,
} from "./counsel-report-model";

const MARGIN = 20;
const FOOTER_H = 16;
const REPORT_TITLE = "Saarthi Counsel Report";
const DEFAULT_DISCLAIMER =
  "This response is generated by an AI system for informational purposes only and does not constitute legal advice. Consult a licensed advocate before acting on this information.";

type RGB = { r: number; g: number; b: number };
type Font = [name: string, style?: string];

const ACCENT: RGB = { r: 154, g: 52, b: 18 }; // burnt amber — the single accent
const ACCENT_SOFT: RGB = { r: 253, g: 230, b: 138 };
const INK: RGB = { r: 15, g: 23, b: 42 };
const SLATE: RGB = { r: 51, g: 65, b: 85 };
const MUTED: RGB = { r: 100, g: 116, b: 139 };
const HAIR: RGB = { r: 226, g: 232, b: 240 };
const DISC_BG: RGB = { r: 248, g: 250, b: 252 };

/** Minimal surface used by the branded report — easy to mock in tests. */
export interface CounselPdfDoc {
  internal: { pageSize: { getWidth: () => number; getHeight: () => number } };
  getNumberOfPages: () => number;
  setPage: (n: number) => void;
  addPage: () => void;
  setFont: (name: string, style?: string) => void;
  setFontSize: (n: number) => void;
  setTextColor: (r: number, g: number, b: number) => void;
  setDrawColor: (r: number, g: number, b: number) => void;
  setFillColor: (r: number, g: number, b: number) => void;
  setLineWidth: (n: number) => void;
  line: (x1: number, y1: number, x2: number, y2: number) => void;
  rect: (x: number, y: number, w: number, h: number, style?: string) => unknown;
  text: (
    text: string | string[],
    x: number,
    y: number,
    opts?: { align?: "left" | "center" | "right"; charSpace?: number },
  ) => void;
  splitTextToSize: (text: string, width: number) => string[];
  /** Optional — present on real jsPDF, absent in the test mock (calls are guarded). */
  addImage?: (data: string, format: string, x: number, y: number, w: number, h: number) => void;
  getImageProperties?: (data: string) => { width: number; height: number };
}

type Block =
  | { kind: "h"; level: 2 | 3; text: string }
  | { kind: "p"; text: string }
  | { kind: "ul"; text: string }
  | { kind: "ol"; index: number; text: string }
  | { kind: "quote"; text: string };

function formatWhen(date: Date): string {
  return date.toLocaleString("en-IN", {
    timeZone: "Asia/Kolkata",
    day: "numeric",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function pad2(n: number): string {
  return String(n).padStart(2, "0");
}

/**
 * Map characters jsPDF's built-in Helvetica cannot encode to safe equivalents.
 * The rupee sign (U+20B9) is the common offender — left as-is it also breaks
 * width measurement, so lines overflow the page. (Devanagari and other
 * non-Latin scripts need an embedded Unicode font — tracked as a follow-up.)
 */
function sanitizeGlyphs(text: string): string {
  return text.replace(/₹\s*/g, "Rs ").replace(/ /g, " ");
}

/** Remove inline markdown emphasis so the PDF shows clean prose. */
function stripInline(text: string): string {
  return sanitizeGlyphs(
    text
      .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
      .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
      .replace(/\*\*(.+?)\*\*/g, "$1")
      .replace(/__(.+?)__/g, "$1")
      .replace(/`([^`]+?)`/g, "$1")
      .replace(/\*\*/g, "")
      .trim(),
  );
}

function parseBlocks(answer: string): Block[] {
  const clean = stripCitationMarkers(answer);
  const out: Block[] = [];
  for (const raw of clean.split(/\n+/)) {
    const line = raw.trim();
    if (!line) continue;

    const heading = /^(#{1,6})\s+(.*)$/.exec(line);
    if (heading) {
      out.push({ kind: "h", level: heading[1].length >= 3 ? 3 : 2, text: stripInline(heading[2]) });
      continue;
    }
    if (/^>\s+/.test(line)) {
      out.push({ kind: "quote", text: stripInline(line.replace(/^>\s+/, "")) });
      continue;
    }
    const ordered = /^(\d+)[.)]\s+(.*)$/.exec(line);
    if (ordered) {
      out.push({ kind: "ol", index: Number(ordered[1]), text: stripInline(ordered[2]) });
      continue;
    }
    if (/^[-*•]\s+/.test(line)) {
      out.push({ kind: "ul", text: stripInline(line.replace(/^[-*•]\s+/, "")) });
      continue;
    }
    out.push({ kind: "p", text: stripInline(line) });
  }
  return out;
}

interface ReportInput {
  title: string;
  reference: string;
  turns: CounselReportTurn[];
  disclaimer?: string;
  mode: "single" | "conversation";
  logo?: string | null;
}

function renderReport(pdf: CounselPdfDoc, input: ReportInput, generatedAt: Date): void {
  const pageW = pdf.internal.pageSize.getWidth();
  const pageH = pdf.internal.pageSize.getHeight();
  const maxW = pageW - MARGIN * 2;
  const logo = input.logo ?? null;
  let y = 0;

  const style = (color: RGB, font: Font, size: number) => {
    pdf.setFont(font[0], font[1] ?? "normal");
    pdf.setFontSize(size);
    pdf.setTextColor(color.r, color.g, color.b);
  };

  const drawRunningHeader = () => {
    style(MUTED, ["helvetica", "normal"], 7.5);
    pdf.text(`MeraBakil · ${input.title}`, MARGIN, MARGIN - 6);
    pdf.text(input.reference, pageW - MARGIN, MARGIN - 6, { align: "right" });
    pdf.setDrawColor(HAIR.r, HAIR.g, HAIR.b);
    pdf.setLineWidth(0.2);
    pdf.line(MARGIN, MARGIN - 3, pageW - MARGIN, MARGIN - 3);
  };

  const newPage = () => {
    pdf.addPage();
    drawRunningHeader();
    y = MARGIN + 3;
  };

  const ensure = (need: number) => {
    if (y + need > pageH - FOOTER_H) newPage();
  };

  const writeFlow = (
    lines: string[],
    opts: { lineH: number; color: RGB; font: Font; size: number; indent?: number; charSpace?: number },
  ) => {
    style(opts.color, opts.font, opts.size);
    for (const line of lines) {
      ensure(opts.lineH);
      pdf.text(line, MARGIN + (opts.indent ?? 0), y, opts.charSpace ? { charSpace: opts.charSpace } : undefined);
      y += opts.lineH;
    }
  };

  const writeListItem = (
    marker: string,
    markerColor: RGB,
    text: string,
    opts: { textIndent: number; markerIndent: number; lineH: number; color: RGB; font: Font; size: number },
  ) => {
    const lines = pdf.splitTextToSize(text, maxW - opts.textIndent);
    lines.forEach((line, idx) => {
      ensure(opts.lineH);
      if (idx === 0) {
        style(markerColor, ["helvetica", "bold"], opts.size);
        pdf.text(marker, MARGIN + opts.markerIndent, y);
      }
      style(opts.color, opts.font, opts.size);
      pdf.text(line, MARGIN + opts.textIndent, y);
      y += opts.lineH;
    });
  };

  const kicker = (label: string) => {
    ensure(9);
    style(ACCENT, ["helvetica", "bold"], 8);
    pdf.text(label.toUpperCase(), MARGIN, y, { charSpace: 0.3 });
    y += 6;
  };

  const hairline = (color: RGB = HAIR, width = 0.2) => {
    ensure(2);
    pdf.setDrawColor(color.r, color.g, color.b);
    pdf.setLineWidth(width);
    pdf.line(MARGIN, y, pageW - MARGIN, y);
  };

  const drawLogo = (x: number, top: number, boxH: number): number => {
    if (logo && typeof pdf.addImage === "function") {
      let w = boxH;
      if (typeof pdf.getImageProperties === "function") {
        try {
          const props = pdf.getImageProperties(logo);
          if (props?.width && props?.height) w = (props.width / props.height) * boxH;
        } catch {
          /* fall back to square */
        }
      }
      try {
        pdf.addImage(logo, "PNG", x, top, w, boxH);
        return w;
      } catch {
        /* fall through to vector monogram */
      }
    }
    pdf.setDrawColor(ACCENT.r, ACCENT.g, ACCENT.b);
    pdf.setLineWidth(0.6);
    pdf.rect(x, top, boxH, boxH);
    style(ACCENT, ["helvetica", "bold"], 10);
    pdf.text("MB", x + boxH / 2, top + boxH / 2 + 1.6, { align: "center" });
    return boxH;
  };

  const drawMasthead = () => {
    const top = 15;
    const markH = 11;
    const markW = drawLogo(MARGIN, top - 1, markH);

    style(INK, ["helvetica", "bold"], 11);
    pdf.text("MeraBakil", MARGIN + markW + 4, top + 4);
    style(MUTED, ["helvetica", "normal"], 7);
    pdf.text("Legal Help. Made Simple.", MARGIN + markW + 4, top + 8.5);

    const rx = pageW - MARGIN;
    style(ACCENT, ["helvetica", "bold"], 7.5);
    pdf.text("CONFIDENTIAL", rx, top + 1.5, { align: "right", charSpace: 0.3 });
    style(MUTED, ["helvetica", "normal"], 8);
    pdf.text(input.reference, rx, top + 6, { align: "right" });
    pdf.text(`Generated ${formatWhen(generatedAt)} IST`, rx, top + 10, { align: "right" });

    const titleY = top + 20;
    style(INK, ["helvetica", "bold"], 17);
    pdf.text(input.title, MARGIN, titleY);

    const ruleY = titleY + 4.5;
    pdf.setDrawColor(ACCENT.r, ACCENT.g, ACCENT.b);
    pdf.setLineWidth(0.5);
    pdf.line(MARGIN, ruleY, pageW - MARGIN, ruleY);

    y = ruleY + 11;
  };

  const renderBlocks = (answer: string) => {
    for (const block of parseBlocks(answer)) {
      if (block.kind === "h") {
        y += block.level === 2 ? 3 : 2;
        writeFlow(pdf.splitTextToSize(block.text, maxW), {
          lineH: block.level === 2 ? 6 : 5.4,
          color: INK,
          font: ["helvetica", "bold"],
          size: block.level === 2 ? 11.5 : 10.2,
        });
        y += 1.5;
      } else if (block.kind === "ul") {
        writeListItem("•", ACCENT, block.text, {
          textIndent: 6,
          markerIndent: 1.5,
          lineH: 5.5,
          color: SLATE,
          font: ["helvetica", "normal"],
          size: 10.5,
        });
        y += 1;
      } else if (block.kind === "ol") {
        writeListItem(`${block.index}.`, INK, block.text, {
          textIndent: 8,
          markerIndent: 0.5,
          lineH: 5.5,
          color: SLATE,
          font: ["helvetica", "normal"],
          size: 10.5,
        });
        y += 1;
      } else if (block.kind === "quote") {
        const lines = pdf.splitTextToSize(block.text, maxW - 10);
        const startY = y;
        writeFlow(lines, {
          lineH: 5.4,
          color: MUTED,
          font: ["helvetica", "italic"],
          size: 10.5,
          indent: 8,
        });
        if (y > startY) {
          pdf.setDrawColor(ACCENT_SOFT.r, ACCENT_SOFT.g, ACCENT_SOFT.b);
          pdf.setLineWidth(1);
          pdf.line(MARGIN + 2, startY - 3.5, MARGIN + 2, y - 4);
        }
        y += 2;
      } else {
        writeFlow(pdf.splitTextToSize(block.text, maxW), {
          lineH: 5.6,
          color: SLATE,
          font: ["helvetica", "normal"],
          size: 10.5,
        });
        y += 2.4;
      }
    }
  };

  const renderSources = (sources: CounselReportSource[]) => {
    sources.slice(0, 12).forEach((src, i) => {
      const title = src.title || src.citation || src.url || `Source ${i + 1}`;
      const extra = [src.citation, src.url].filter(Boolean).join("  ·  ");
      const line = sanitizeGlyphs(extra && extra !== title ? `${title} — ${extra}` : title);
      writeListItem(`${i + 1}.`, MUTED, line, {
        textIndent: 8,
        markerIndent: 0.5,
        lineH: 5.2,
        color: SLATE,
        font: ["helvetica", "normal"],
        size: 9.5,
      });
    });
  };

  const drawTurn = (turn: CounselReportTurn, index: number) => {
    kicker(input.mode === "single" ? "Your question" : `${pad2(index + 1)} · Question`);
    const question = sanitizeGlyphs(stripCitationMarkers(turn.question || "—"));
    writeFlow(pdf.splitTextToSize(question, maxW), {
      lineH: 6,
      color: SLATE,
      font: ["helvetica", "normal"],
      size: 12,
    });
    y += 6;

    kicker("Counsel note");
    renderBlocks(turn.answer || "");

    const sources = turn.sources ?? [];
    if (sources.length) {
      y += 3;
      hairline();
      y += 6;
      kicker("Sources");
      renderSources(sources);
    }
  };

  const drawDisclaimer = (text?: string) => {
    const disc = sanitizeGlyphs(text?.trim() || DEFAULT_DISCLAIMER);
    y += 10;
    const lines = pdf.splitTextToSize(disc, maxW - 12);
    const boxH = lines.length * 4.6 + 12;
    ensure(boxH + 2);
    pdf.setFillColor(DISC_BG.r, DISC_BG.g, DISC_BG.b);
    pdf.setDrawColor(HAIR.r, HAIR.g, HAIR.b);
    pdf.setLineWidth(0.3);
    pdf.rect(MARGIN, y, maxW, boxH, "FD");
    style(ACCENT, ["helvetica", "bold"], 7.5);
    pdf.text("IMPORTANT", MARGIN + 6, y + 6, { charSpace: 0.3 });
    style(MUTED, ["helvetica", "normal"], 8.5);
    let ty = y + 11;
    for (const line of lines) {
      pdf.text(line, MARGIN + 6, ty);
      ty += 4.6;
    }
    y += boxH;
  };

  const drawFooters = () => {
    const pages = pdf.getNumberOfPages();
    for (let i = 1; i <= pages; i += 1) {
      pdf.setPage(i);
      pdf.setDrawColor(HAIR.r, HAIR.g, HAIR.b);
      pdf.setLineWidth(0.2);
      pdf.line(MARGIN, pageH - 13, pageW - MARGIN, pageH - 13);
      style(MUTED, ["helvetica", "normal"], 8);
      pdf.text("Confidential · merabakil.in", MARGIN, pageH - 8);
      pdf.text("MeraBakil · Saarthi", pageW / 2, pageH - 8, { align: "center" });
      pdf.text(`${i} / ${pages}`, pageW - MARGIN, pageH - 8, { align: "right" });
    }
  };

  drawMasthead();
  input.turns.forEach((turn, i) => {
    drawTurn(turn, i);
    if (input.mode === "conversation" && i < input.turns.length - 1) {
      y += 7;
      hairline(HAIR, 0.2);
      y += 9;
    }
  });
  drawDisclaimer(input.disclaimer);
  drawFooters();
}

export function drawCounselReport(
  pdf: CounselPdfDoc,
  payload: CounselReportPayload,
  generatedAt = new Date(),
  logo: string | null = null,
): void {
  renderReport(
    pdf,
    {
      title: REPORT_TITLE,
      reference: reportReference(generatedAt, "SCR"),
      turns: [{ question: payload.question, answer: payload.answer, sources: payload.sources }],
      disclaimer: payload.disclaimer,
      mode: "single",
      logo,
    },
    generatedAt,
  );
}

export function drawConversationReport(
  pdf: CounselPdfDoc,
  payload: ConversationReportPayload,
  generatedAt = new Date(),
  logo: string | null = null,
): void {
  renderReport(
    pdf,
    {
      title: REPORT_TITLE,
      reference: reportReference(generatedAt, "SCT"),
      turns: payload.turns,
      disclaimer: payload.disclaimer,
      mode: "conversation",
      logo,
    },
    generatedAt,
  );
}

/** Load the brand mark as a data URL for embedding; null if unavailable. */
async function loadBrandMark(): Promise<string | null> {
  if (typeof window === "undefined" || typeof fetch === "undefined") return null;
  try {
    const res = await fetch(brandUrl("/brand/mark-light.png"));
    if (!res.ok) return null;
    const blob = await res.blob();
    return await new Promise<string | null>((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(typeof reader.result === "string" ? reader.result : null);
      reader.onerror = () => resolve(null);
      reader.readAsDataURL(blob);
    });
  } catch {
    return null;
  }
}

export async function downloadCounselReportPdf(payload: CounselReportPayload): Promise<void> {
  const [{ jsPDF }, logo] = await Promise.all([import("jspdf"), loadBrandMark()]);
  const pdf = new jsPDF({ unit: "mm", format: "a4" });
  drawCounselReport(pdf, payload, new Date(), logo);
  pdf.save(counselReportFilename());
}

export async function downloadConversationReportPdf(payload: ConversationReportPayload): Promise<void> {
  const [{ jsPDF }, logo] = await Promise.all([import("jspdf"), loadBrandMark()]);
  const pdf = new jsPDF({ unit: "mm", format: "a4" });
  drawConversationReport(pdf, payload, new Date(), logo);
  pdf.save(conversationReportFilename());
}

/** Test hook: same payload is used for download. */
export function counselReportPlaintext(payload: CounselReportPayload): string {
  return formatCounselReportPlaintext(payload);
}
